import {initTrials,validateTrials,syncTrialHealing} from './trials.js?v=0.9.0';
import {trialChoices} from '../content/trials.js?v=0.9.0';
import {initLiving,validateLiving} from './living-world.js?v=0.8.0';
import {validateGrowth} from './growth.js?v=0.7.0';
import {relicChoices,ROUTES} from '../content/journeys.js?v=0.6.0';
import {DUNGEONS} from '../content/adventures.js?v=0.3.1';
import {makeHero,createItem,uid,derive,clamp,equip} from './rules.js?v=0.3.1';
import {CLASSES,EFFECTS} from '../content/classes.js?v=0.3.1';import {ITEM_TEMPLATES,ZONES,ENEMIES} from '../content/region.js?v=0.3.1';
export const SAVE_KEY='vyriy-save-v2';
export function migrateV1(old,classId='swordsman',name='Мандрівник'){let base=old.heroes?.[0];let h=makeHero(classId,name);if(!base)return h;h.level=clamp(Math.floor(base.base||1),1,85);h.skillPoints=2+h.level-1;h.xp=Math.max(0,base.xp||0);h.zeny=Math.max(0,old.zeny||0);let spent=0;for(let k of Object.keys(h.stats)){let oldVal=clamp(Math.floor(base.stats?.[k]||4),1,99);h.stats[k]=Math.max(h.stats[k],oldVal);spent+=Math.max(0,h.stats[k]-CLASSES[classId].stat[k]);}h.statPoints=Math.max(0,5+(h.level-1)*5-spent);for(let [id,n]of Object.entries(old.inventory||{})){let template=ITEM_TEMPLATES[id]?id:id.startsWith('card:')?'rune':null;if(template)for(let j=0;j<Math.min(500,Math.max(0,n));j++)h.inventory.push(createItem(template,h.id));}for(let template of Object.values(base.gear||{})){if(ITEM_TEMPLATES[template]){let item=createItem(template,h.id);h.inventory.push(item);equip(h,item.id);}}for(let card of Object.values(base.cards||{}))if(card)h.inventory.push(createItem('rune',h.id));let d=derive(h);h.hp=d.hp;h.sp=d.sp;return h;}
export function loadSave(){try{let raw=localStorage.getItem(SAVE_KEY);if(!raw)return null;let s=JSON.parse(raw);if(![2,3].includes(s.version)||!s.players||!ZONES[s.zone])return null;return upgradeSave(s);}catch{return null;}}
export function saveLocal(s){try{localStorage.setItem(SAVE_KEY,JSON.stringify(s));return true}catch{return false}}
export function getLegacy(){try{return JSON.parse(localStorage.getItem('vyriy-save-v1'))}catch{return null}}
export function validateImported(s){if(![2,3].includes(s?.version)||!ZONES[s.zone]||!s.players||Object.keys(s.players).length!==1||!Array.isArray(s.enemies)||!Array.isArray(s.claims)||!s.flags||!Array.isArray(s.flags.seals))throw Error('Невірне збереження');let h=Object.values(s.players)[0];if(!CLASSES[h.classId]||typeof h.name!=='string'||!h.inventory||h.inventory.length>10000||!h.stats||!h.equipment||!Array.isArray(h.effects)||!h.cooldowns||!h.specs)throw Error('Невірний герой');for(let n of ['level','xp','hp','sp','statPoints','zeny','x','y'])if(!Number.isFinite(h[n])||h[n]<0)throw Error('Невірні характеристики');if(h.level<1||h.level>85)throw Error('Невірний рівень');for(let n of Object.keys(CLASSES[h.classId].stat))if(!Number.isFinite(h.stats[n])||h.stats[n]<1||h.stats[n]>99)throw Error('Невірні характеристики');if(s.players&&Object.values(s.players).some(p=>p.echoes!==undefined&&(!Number.isSafeInteger(p.echoes)||p.echoes<0)))throw Error('Невірний баланс відлунь');for(let [id,tuning] of Object.entries(h.skillTuning||{})){if(!CLASSES[h.classId].skills.some(a=>a.id===id)||!tuning||typeof tuning!=='object'||Object.entries(tuning).some(([key,n])=>!['crit','afterglow'].includes(key)||!Number.isInteger(n)||n<0||n>5))throw Error('Невірне підсилення навички');}for(let [id,choice]of Object.entries(h.skillAugments||{}))if(!CLASSES[h.classId].skills.some(a=>a.id===id)||!['force','rhythm'].includes(choice))throw Error('Невірний напрям навички');if(h.storage!==undefined&&(!Array.isArray(h.storage)||h.storage.length>500))throw Error('Невірне сховище');if(h.dungeonRewards!==undefined&&(!Array.isArray(h.dungeonRewards)||h.dungeonRewards.length>10||new Set(h.dungeonRewards.map(r=>r.id)).size!==h.dungeonRewards.length||h.dungeonRewards.some(r=>typeof r.id!=='string'||typeof r.runId!=='string'||!DUNGEONS[r.zone]||!Object.hasOwn(ROUTES,r.route)||!Number.isInteger(r.level)||r.level<1||r.level>85||!Array.isArray(r.choices)||r.choices.length!==3||!Number.isInteger(r.trial??0)||(r.trial??0)<0||(r.trial??0)>3||r.choices.some((c,n)=>c!==(r.trial?trialChoices(h.classId):['resources',...relicChoices(h.classId)])[n]))))throw Error('Невірні нагороди експедиції');if((h.storage||[]).some(i=>ITEM_TEMPLATES[i.template]?.kind==='quest'||Object.values(h.equipment).includes(i.id)))throw Error('Квестовий або споряджений предмет у сховищі');validateGrowth(h);validateLiving(h);validateTrials(h);let ids=new Set;for(let item of [...h.inventory,...(h.storage||[])]){if(!ITEM_TEMPLATES[item.template]||typeof item.id!=='string'||ids.has(item.id)||item.owner!==h.id)throw Error('Невірні предмети');if(!Number.isInteger(item.quality??0)||(item.quality??0)<0||(item.quality??0)>5)throw Error('Невірне гартування');ids.add(item.id);}h.effects=h.effects.filter(e=>EFFECTS[e.id]&&Number.isFinite(e.left)&&e.left>0&&e.left<120&&Number.isFinite(e.stacks)&&e.stacks>=1&&e.stacks<=3);s.events=[];return upgradeSave(s);}

export function upgradeSave(s){let previous=s.version;s.version=3;s.flags??={seals:[]};s.flags.zoneBosses??={};s.encounterObjects??=[];s.fields??=[];s.echoCasts??=[];s.journeyCooldowns??={};for(const e of s.enemies||[])if(ENEMIES[e.type]?.tactic){e.tactic=ENEMIES[e.type].tactic;e.role=ENEMIES[e.type].role;}if(s.flags.boss)s.flags.zoneBosses.crypt=true;if(s.flags.seals?.length===3)s.flags.sealsReady=true;for(let h of Object.values(s.players||{})){let c=CLASSES[h.classId];h.skillPoints??=2+Math.max(0,h.level-1);h.skillRanks??=Object.fromEntries(c.skills.map((a,i)=>[a.id,i<2?1:0]));for(let a of c.skills)h.skillRanks[a.id]??=0;h.skillbar??=c.skills.slice(0,2).map(a=>a.id);h.equipment.accessory??=null;h.quests??={};h.counters??={};h.echoes??=0;h.skillTuning??={};h.skillAugments??={};h.bestiary??=Object.fromEntries(Object.keys(ENEMIES).filter(id=>(h.counters?.['kill:'+id]||0)>0).map(id=>[id,{kills:h.counters['kill:'+id],trophies:0}]));h.builds??=[null,null];initLiving(h);initTrials(h);h.storage??=[];h.dungeonRewards??=[];h.navigationMode??='quest';for(let item of [...h.inventory,...h.storage])item.rarity??=ITEM_TEMPLATES[item.template]?.rarity||'common';}if(previous===2){s.contentRevision=2;s.projectiles=[];for(let h of Object.values(s.players||{})){h.cast=null;h.target=null;h.auto=false;}}syncTrialHealing(s);return s;}
